def transform3(grid):
    """
    Rule derived from demos:
    1. Find h_crosses (same non-zero value rows) and v_cross (same non-zero value col)
    2. Find the FIRST band (from top) with non-zero data - this is the SOURCE band
    3. src = left side (cols before v_cross) of source band
    4. The FIRST band from top (before first h_cross): fill right side with src (same num rows as top band, using src rows in order)
    5. The SECOND band from top (between first two h_crosses): fill both sides with src (same num rows as middle band)
    """
    H, W = len(grid), len(grid[0])

    # Find h_crosses
    h_crosses = []
    for r in range(H):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            h_crosses.append(r)

    if len(h_crosses) < 2:
        return grid

    h_crosses.sort()

    # Find v_cross
    v_cross = None
    for c in range(W):
        col_vals = [grid[r][c] for r in range(H)]
        if len(set(col_vals)) == 1 and col_vals[0] != 0:
            v_cross = c
            break

    if v_cross is None:
        return grid

    cross_val = grid[h_crosses[0]][0]

    # Find all bands
    bands = []
    cur = 0
    j = 0
    while j < len(h_crosses):
        band_start = cur
        band_end = h_crosses[j]
        if band_end > band_start:
            has_nonzero = False
            for r in range(band_start, band_end):
                for c in range(W):
                    if c != v_cross and grid[r][c] != 0:
                        has_nonzero = True
                        break
                if has_nonzero:
                    break
            bands.append((band_start, band_end, has_nonzero))
        cur = h_crosses[j] + 1
        j += 1

    if cur < H:
        has_nonzero = False
        for r in range(cur, H):
            for c in range(W):
                if c != v_cross and grid[r][c] != 0:
                    has_nonzero = True
                    break
        bands.append((cur, H, has_nonzero))

    if len(bands) < 2:
        return grid

    # Top band gets right fill, middle band gets both fill
    src = []
    if bands[0][2]:  # top band has non-zero
        # Source from top band
        for r in range(bands[0][0], bands[0][1]):
            src.append(grid[r][:v_cross])
    elif bands[1][2]:  # middle band has non-zero
        # Source from middle band - flow upward
        for r in range(bands[1][0], bands[1][1]):
            src.append(grid[r][:v_cross])
    else:  # bottom or later band
        # Find first non-zero band
        for band in bands:
            if band[2]:
                src_start = band[0]
                src_end = band[1]
                for r in range(src_start, src_end):
                    src.append(grid[r][:v_cross])
                break

    # Fill top band (right side only)
    top_start, top_end = bands[0][0], bands[0][1]
    top_len = top_end - top_start
    for r in range(top_start, top_end):
        row_idx_in_src = r - top_start
        if row_idx_in_src < len(src):
            for c in range(v_cross + 1, V cross + 1 + len(src[0])):
                if c < W:
                    output[r][c] = src[row_idx_in_src][c - (v_cross + 1)]

    # Fill middle band (both sides)
    middle_start, middle_end = bands[1][0], bands[1][1]
    for r in range(middle_start, middle_end):
        row_idx_in_band = r - middle_start
        if row_idx_in_band < len(src):
            src_row = src[row_idx_in_band]
            for c in range(v_cross):
                output[r][c] = src_row[c]
            for c in range(v_cross + 1, W):
                offset = c - (v_cross + 1)
                if offset < len(src[0]):
                    output[r][c] = src_row[offset]

    # Fill cross
    for r in h_crosses:
        output[r] = [cross_val] * W
    for c in range(W):
        if c == v_cross:
            for r in range(H):
                output[r][c] = cross_val

    return output

